def max_value_on_paths(N, grid_values):
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        grid[x][y] = value

    # Initialize the maximum sum to 0
    max_sum = 0

    # Iterate over each position in the grid
    for x in range(N):
        for y in range(N):
            # If the current position is not the top-left corner, skip it
            if x == 0 and y == 0:
                continue

            # If the current position is the bottom-right corner, update the maximum sum
            if x == N - 1 and y == N - 1:
                max_sum = max(max_sum, grid[x][y])

            # If the current position is not the bottom-right corner, update the maximum sum
            else:
                max_sum = max(max_sum, grid[x][y] + max(grid[x - 1][y], grid[x][y - 1]))

    return max_sum
```

