def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    num_separated = [[0] * (N + 1) for _ in range(M + 1)]

    # Loop through each chatting pair and count the number of positions where an aisle can be added to separate them
    for x1, y1, x2, y2 in chatting_pairs:
        for x in range(x1, x2 + 1):
            for y in range(y1, y2 + 1):
                num_separated[x][y] += 1

    # Initialize variables to store the optimal row and column indices for the aisles
    row_indices = []
    col_indices = []

    # Loop through each position and check if it is the optimal position for an aisle
    for x in range(1, M + 1):
        for y in range(1, N + 1):
            if num_separated[x][y] == D:
                row_indices.append(x)
                col_indices.append(y)

    # Return the optimal row and column indices for the aisles
    return " ".join(str(x) for x in row_indices), " ".join(str(y) for y in col_indices)
