def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff != 0:
            result += f"{coeff if coeff != 1 or i == 0 else ''}x{'^' + str(i) if i > 1 else '' if i == 1 else ''}"
            if i != n:
                result += coeff < 0 and " - " or " + "
