def decode(encoded: str, original: str, message: str) -> str:
    # Initialize a dictionary to map encoded letters to their original letters
    mapping = {}

    # Iterate over the encoded string
    for i in range(len(encoded)):
        # If the encoded letter is not already in the mapping, add it
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        # If the encoded letter is already in the mapping and maps to a different original letter, return "Failed"
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    # Initialize a string to store the decoded message
    decoded = ""

    # Iterate over the encrypted message
    for letter in message:
        # If the letter is in the mapping, add the corresponding original letter to the decoded message
        if letter in mapping:
            decoded += mapping[letter]
        # If the letter is not in the mapping, return "Failed"
        else:
            return "Failed"

    # Return the decoded message
    return decoded
```

